function StatusGlyph({ status, muted }: { status: TestStatus; muted?: boolean }) {
  const base = cn(
    "grid size-4 shrink-0 place-items-center [&_svg]:size-3.5",
    muted && "text-chatcn-fg-faint!",
  )
  switch (status) {
    case "passed":
      return (
        <span className={cn(base, "text-(color:--chatcn-green)")}>
          <CheckIcon aria-hidden="true" />
        </span>
      )
    case "failed":
      return (
        <span className={cn(base, "text-(color:--chatcn-red)")}>
          <CircleXIcon aria-hidden="true" />
        </span>
      )
    case "skipped":
      return (
        <span className={cn(base, "text-(color:--chatcn-fg-faint)")}>
          <CircleDashedIcon aria-hidden="true" />
        </span>
      )
    case "running":
      return (
        <span className={cn(base, "text-(color:--chatcn-blue)")}>
          <Spinner />
        </span>
      )
    default:
      return (
        <span className={cn(base, "text-(color:--chatcn-fg-faint) [&_svg]:size-3")}>
          <CircleIcon aria-hidden="true" />
        </span>
      )
  }
}

/* -------------------------------------------------------------------------------------------------
