function CountToggle({
  status,
  count,
  pressed,
  onPress,
}: {
  status: "failed" | "passed" | "skipped"
  count: number
  pressed: boolean
  onPress: () => void
}) {
  return (
    <button
      type="button"
      aria-pressed={pressed}
      disabled={count === 0 && !pressed}
      onClick={onPress}
      className={cn(
        "chatcn-focus rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] inline-flex h-7 items-center gap-1.5 px-2 tabular-nums",
        "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) ease-(--chatcn-ease-standard) transition-colors duration-150",
        "disabled:pointer-events-none disabled:opacity-50 pointer-coarse:h-11",
        pressed && "bg-(color:--chatcn-fill-active) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-active)",
      )}
    >
      <StatusGlyph status={status} muted={count === 0} />
      <span
        className={cn(
          "font-medium",
          status === "failed" && count > 0 ? "text-(color:--chatcn-red)" : "text-(color:--chatcn-fg)",
        )}
      >
        {count}
      </span>
      <span>{status}</span>
    </button>
  )
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const NBSP = "\u00a0"

/** A minute and up: "4 m 12 s", then "2 h 5 m", then "3 d 4 h", never "1 m 60 s". */
function formatLong(seconds: number) {
  const t = Math.round(seconds)
  if (t < 3600) return `${Math.floor(t / 60)}${NBSP}m ${t % 60}${NBSP}s`
  const h = Math.floor(t / 3600)
  if (h < 24) return `${h}${NBSP}h ${Math.floor((t % 3600) / 60)}${NBSP}m`
  return `${Math.floor(h / 24)}${NBSP}d ${h % 24}${NBSP}h`
}

function formatDuration(ms: number) {
  if (ms < 1000) return `${Math.max(0, Math.round(ms))}${NBSP}ms`
  const s = ms / 1000
  if (s < 60) return `${s < 10 ? s.toFixed(2) : s.toFixed(1)}${NBSP}s`
  return formatLong(s)
}

