/** The status a file shows: a failure wins, then running, then queued. */
function fileStatus(tests: TestCase[]): TestStatus {
  if (tests.some((t) => t.status === "failed")) return "failed"
  if (tests.some((t) => t.status === "running")) return "running"
  if (tests.some((t) => t.status === "queued")) return "queued"
  if (tests.every((t) => t.status === "skipped")) return "skipped"
  return "passed"
}

