interface ParsedStack {
  name?: string
  message?: string
  frames: StackFrame[]
}

/* -------------------------------------------------------------------------------------------------
 * Parsing
 * -----------------------------------------------------------------------------------------------*/

const V8_FRAME = /^\s*at\s+(?:(async)\s+)?(?:(.*?)\s+\((.*)\)|(.*))\s*$/

const LOCATION = /^(.*?):(\d+)(?::(\d+))?$/

function splitLocation(location: string) {
  const clean = location
    .replace(/^file:\/\//, "")
    .replace(/^webpack-internal:\/\/\/(\([^)]*\)\/)?/, "")
  const m = clean.match(LOCATION)
  if (!m) return { file: clean || undefined }
  return { file: m[1], line: Number(m[2]), column: m[3] ? Number(m[3]) : undefined }
}

function classify(file: string | undefined): { kind: StackFrameKind; pkg?: string } {
  if (!file) return { kind: "internal" }
  if (/^(node:|internal\/)/.test(file)) return { kind: "internal", pkg: "node" }
  if (/^(native|<anonymous>)/.test(file)) return { kind: "internal", pkg: "runtime" }
  const nm = file.match(/node_modules\/(?:\.pnpm\/[^/]+\/node_modules\/)?((?:@[^/]+\/)?[^/]+)/)
  if (nm) return { kind: "dependency", pkg: nm[1] }
  return { kind: "app" }
}

const GECKO_FRAME = /^\s*(.*?)@(.*?)(?::(\d+))?(?::(\d+))?\s*$/

/** Parses `error.stack` text into a name, message and frames. */
function parseStackTrace(trace: string): ParsedStack {
  const lines = trace.replace(/\r\n/g, "\n").split("\n")
  const frames: StackFrame[] = []
  const head: string[] = []
  for (const raw of lines) {
    const v8 = raw.match(V8_FRAME)
    if (v8) {
      const location = v8[3] ?? v8[4] ?? ""
      const fn = v8[2]?.replace(/^new\s+/, "new ")
      const loc = splitLocation(location)
      frames.push({
        fn: fn || undefined,
        async: v8[1] === "async",
        raw: raw.trim(),
        ...loc,
        ...classify(loc.file),
      })
      continue
    }
    // Firefox and Safari: `fn@url:line:col`, no spaces before the location.
    const gecko = /^[^\s@]*@\S+:\d+/.test(raw.trim()) ? raw.trim().match(GECKO_FRAME) : null
    if (gecko) {
      const loc = splitLocation(
        `${gecko[2]}${gecko[3] ? `:${gecko[3]}` : ""}${gecko[4] ? `:${gecko[4]}` : ""}`,
      )
      frames.push({ fn: gecko[1] || undefined, raw: raw.trim(), ...loc, ...classify(loc.file) })
      continue
    }
    if (frames.length === 0 && raw.trim()) head.push(raw)
  }
  const first = head.join("\n")
  const m = first.match(/^([\w$.]*(?:Error|Exception|Warning)|[A-Z][\w$]*):\s?([\s\S]*)$/)
  return m ? { name: m[1], message: m[2], frames } : { message: first || undefined, frames }
}

type Group =
  | { type: "app"; frame: StackFrame; index: number }
  | { type: "folded"; frames: StackFrame[]; key: string }

function groupFrames(frames: StackFrame[]): Group[] {
  const groups: Group[] = []
  frames.forEach((frame, index) => {
    if (frame.kind === "app") {
      groups.push({ type: "app", frame, index })
      return
    }
    const last = groups.at(-1)
    if (last?.type === "folded") last.frames.push(frame)
    else groups.push({ type: "folded", frames: [frame], key: `f${index}` })
  })
  return groups
}

