function FileGroup({
  file,
  tests,
  shown,
  filter,
  ...rest
}: {
  file: string
  tests: TestCase[]
  shown: TestCase[]
  filter: TestFilter
  onRerun?: (test: TestCase) => void
  appRoot?: string
  getFrameHref?: StackTraceProps["getFrameHref"]
  running: boolean
}) {
  const status = fileStatus(tests)
  const failed = status === "failed"
  // Files open by themselves when they fail, until the reader toggles them.
  const [open, setOpen] = React.useState(failed)
  const touched = React.useRef(false)
  React.useEffect(() => {
    if (failed && !touched.current) setOpen(true)
  }, [failed])
  // A filter is a request to see those tests, so it opens every file that has them.
  React.useEffect(() => {
    if (filter !== "all") setOpen(true)
  }, [filter])
  const duration = tests.reduce((sum, t) => sum + (t.durationMs ?? 0), 0)
  const failures = tests.filter((t) => t.status === "failed").length

  return (
    <li data-slot="test-results-file" data-test-status={status}>
      <Collapsible.Root
        open={open}
        onOpenChange={(next) => {
          touched.current = true
          setOpen(next)
        }}
      >
        <Collapsible.Trigger
          className={cn(
            "group/trigger flex h-9 w-full min-w-0 items-center gap-2 ps-3 pe-3 text-start outline-none pointer-coarse:h-11",
            "hover:bg-(color:--chatcn-fill-hover)",
            "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
          )}
        >
          <Chevron />
          <StatusGlyph status={status} />
          <span className="sr-only">{STATUS_WORD[status]}: </span>
          <span
            className={cn(
              "text-[0.8125rem]/[1.25rem] min-w-0 truncate font-mono",
              status === "failed" || status === "running"
                ? "text-(color:--chatcn-fg)"
                : "text-(color:--chatcn-fg-muted)",
            )}
          >
            {file}
          </span>
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
            {tests.length} {tests.length === 1 ? "test" : "tests"}
            {failures > 0 ? (
              <span className="text-(color:--chatcn-red)">{`, ${failures} failed`}</span>
            ) : null}
          </span>
          <span className="flex-1" />
          {duration > 0 ? (
            <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
              {formatDuration(duration)}
            </span>
          ) : null}
        </Collapsible.Trigger>
        <Collapsible.Panel className={panelClass}>
          <ul className="pb-1">
            {shown.map((test) => (
