export function TestResults({
  tests,
  running = false,
  total,
  durationMs,
  title = "Tests",
  onRerunFailed,
  onRerun,
  filter: filterProp,
  defaultFilter = "all",
  onFilterChange,
  appRoot,
  getFrameHref,
  maxHeight,
  className,
  ...props
}: TestResultsProps) {
  const [filterState, setFilterState] = React.useState<TestFilter>(defaultFilter)
  const filter = filterProp ?? filterState
  const setFilter = (next: TestFilter) => {
    if (filterProp === undefined) setFilterState(next)
    onFilterChange?.(next)
  }

  const counts = React.useMemo(() => {
    const c = { passed: 0, failed: 0, skipped: 0, running: 0, queued: 0 }
    for (const t of tests) c[t.status]++
    return c
  }, [tests])
  const finished = counts.passed + counts.failed + counts.skipped
  const expected = Math.max(total ?? tests.length, tests.length, 1)
  const progress = Math.min(1, finished / expected)

  const files = React.useMemo(() => {
    const map = new Map<string, TestCase[]>()
    for (const t of tests) {
      const list = map.get(t.file)
      if (list) list.push(t)
      else map.set(t.file, [t])
    }
    return [...map.entries()]
  }, [tests])

  const visibleFiles = files
    .map(([file, list]) => ({ file, list, shown: list.filter((t) => matches(t, filter)) }))
    .filter((f) => f.shown.length > 0)

  const toggle = (status: "failed" | "passed" | "skipped") =>
    setFilter(filter === status ? "all" : status)

  return (
    <div
      data-slot="test-results"
      data-test-state={
        running ? "running" : counts.failed > 0 ? "failed" : tests.length ? "passed" : "empty"
      }
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) text-(color:--chatcn-fg) relative flex flex-col overflow-hidden",
        "forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <div
        data-slot="test-results-header"
        className="border-(color:--chatcn-border)/70 relative flex min-h-11 flex-wrap items-center gap-x-1 gap-y-1 border-b py-1.5 ps-3.5 pe-3.5"
      >
        <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] me-2 font-medium">{title}</span>
        {running ? (
          <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) me-1 inline-flex items-center gap-1.5 tabular-nums">
            <Spinner className="text-(color:--chatcn-fg)" />
            {`${finished} of ${expected}`}
          </span>
        ) : null}
        {/* biome-ignore lint/a11y/useSemanticElements: a fieldset is for form controls */}
        <span className="flex items-center" role="group" aria-label="Filter by status">
          <CountToggle
            status="failed"
            count={counts.failed}
            pressed={filter === "failed"}
            onPress={() => toggle("failed")}
          />
          <CountToggle
            status="passed"
            count={counts.passed}
            pressed={filter === "passed"}
            onPress={() => toggle("passed")}
          />
          {counts.skipped > 0 || filter === "skipped" ? (
            <CountToggle
              status="skipped"
              count={counts.skipped}
              pressed={filter === "skipped"}
              onPress={() => toggle("skipped")}
            />
          ) : null}
        </span>
        <span className="flex-1" />
        {!running && durationMs !== undefined ? (
          <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) me-1 tabular-nums">
            {formatDuration(durationMs)}
          </span>
        ) : null}
        {/* Only offered when it can do something: a disabled button with nothing to rerun is noise. */}
        {onRerunFailed && !running && counts.failed > 0 ? (
          <Button
            size="sm"
            variant="outline"
            onClick={onRerunFailed}
            className="pointer-coarse:h-11"
          >
            <RotateCcwIcon />
            Rerun failed
          </Button>
        ) : null}
        {/* Determinate progress: 2 px, ink fill, scaled rather than resized. */}
        <span
          aria-hidden="true"
          className={cn(
            "bg-(color:--chatcn-fill) absolute inset-x-0 -bottom-px h-0.5 overflow-hidden",
            "ease-(--chatcn-ease-out) transition-opacity duration-150",
            running ? "opacity-100" : "opacity-0",
          )}
        >
          <span
            className="bg-(color:--chatcn-accent) block h-full origin-left transition-transform duration-300 ease-linear rtl:origin-right"
            style={{ transform: `scaleX(${progress})` }}
          />
        </span>
      </div>
      {running ? (
        <span
          role="progressbar"
          aria-label="Tests run"
          aria-valuemin={0}
          aria-valuemax={expected}
          aria-valuenow={finished}
          className="sr-only"
        />
      ) : null}

      <div style={{ maxHeight }} className="chatcn-scroll min-h-0 overflow-auto">
        {tests.length === 0 ? (
          <div className="flex flex-col gap-1 px-4 py-8 text-center">
            <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium">
              {running ? "Collecting tests…" : "No tests found"}
            </p>
            {running ? null : (
              <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) text-pretty">
                Test files need to match the include pattern in your test config, for example{" "}
                <code className="font-mono">**/*.test.ts</code>.
              </p>
            )}
          </div>
        ) : visibleFiles.length === 0 ? (
          <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) px-4 py-6 text-center">
            No {filter} tests.{" "}
            <button
              type="button"
              onClick={() => setFilter("all")}
              className="chatcn-focus rounded-(--chatcn-radius-xs) text-(color:--chatcn-fg) underline underline-offset-2"
            >
              Show all
            </button>
          </p>
        ) : (
          <ul aria-label="Test files" className="py-1">
            {visibleFiles.map(({ file, list, shown }) => (
              <FileGroup
                key={file}
                file={file}
                tests={list}
                shown={shown}
                filter={filter}
                onRerun={onRerun}
                appRoot={appRoot}
                getFrameHref={getFrameHref}
                running={running}
              />
            ))}
          </ul>
        )}
      </div>

      <span aria-live="polite" className="sr-only">
        {running
          ? ""
          : tests.length
            ? `${counts.failed} failed, ${counts.passed} passed, ${counts.skipped} skipped`
            : ""}
      </span>
    </div>
  )
}

export default TestResults

