function TestResultsDemo() {
  const [phase, setPhase] = React.useState<Phase>({ kind: "running", done: 0 })

  React.useEffect(() => {
    let id: number
    if (phase.kind === "running") {
      id = window.setTimeout(
        () =>
          setPhase(
            phase.done >= PLAN.length
              ? { kind: "done", fixed: false }
              : { kind: "running", done: phase.done + 1 },
          ),
        phase.done === 0 ? 500 : 180 + ((phase.done * 37) % 160),
      )
    } else if (phase.kind === "rerun") {
      id = window.setTimeout(() => setPhase({ kind: "done", fixed: true }), 1100)
    } else {
      // Rerun by itself after a while if nobody clicks, then start over.
      id = window.setTimeout(
        () => setPhase(phase.fixed ? { kind: "running", done: 0 } : { kind: "rerun" }),
        phase.fixed ? 4000 : 6000,
      )
    }
    return () => window.clearTimeout(id)
  }, [phase])

  const tests: TestCase[] = PLAN.map(({ result, ...t }, i) => {
    if (phase.kind === "running") {
      if (i < phase.done) return { ...t, status: result }
      if (i === phase.done)
        return { ...t, status: "running", durationMs: undefined, error: undefined }
      return { ...t, status: "queued", durationMs: undefined, error: undefined }
    }
    if (result === "failed") {
      if (phase.kind === "rerun")
        return { ...t, status: "running", durationMs: undefined, error: undefined }
      if (phase.kind === "done" && phase.fixed)
        return { ...t, status: "passed", durationMs: 58, error: undefined }
    }
    return { ...t, status: result }
  })

  return (
    <div className="w-full max-w-2xl">
      <TestResults
        tests={tests}
        running={phase.kind !== "done"}
        total={phase.kind === "rerun" ? undefined : PLAN.length}
        durationMs={phase.kind === "done" ? (phase.fixed ? 1180 : 2310) : undefined}
        onRerunFailed={() => setPhase({ kind: "rerun" })}
        onRerun={() => setPhase({ kind: "rerun" })}
        appRoot="/Users/mira/code/checkout"
        getFrameHref={(frame) =>
          frame.kind === "app"
            ? `vscode://file${frame.file}:${frame.line}:${frame.column}`
            : undefined
        }
        maxHeight={460}
      />
    </div>
  )
}

/** The line under each 21st demo that points back to the kit. */
function MoreOn({ slug, children }: { slug: string; children: React.ReactNode }) {
  return (
